import { useMemo } from "react";
import { propsToDataAttrs } from "@/registry/nextjs/lib/utilities";
import "@/registry/nextjs/components/row/row.css";



interface LkRowProps extends React.HTMLAttributes<HTMLDivElement> {
  alignItems?: "start" | "center" | "end" | "stretch";
  justifyContent?: "start" | "center" | "end" | "space-between" | "space-around";
  gap?: LkSizeUnit;
  wrapChildren?: boolean;
  defaultChildBehavior?: "auto-grow" | "auto-shrink" | "ignoreFlexRules" | "ignoreIntrinsicSize";
}

export default function Row(props: LkRowProps) {
  const {
    children,
    alignItems="start",
    justifyContent="start",
    gap,
    wrapChildren,
    defaultChildBehavior,
    ...restProps
  } = props;

  const lkRowAttrs = useMemo(
    () =>
      propsToDataAttrs(
        { alignItems, justifyContent, gap, wrapChildren, defaultChildBehavior },
        "row"
      ),
    [alignItems, justifyContent, gap, wrapChildren, defaultChildBehavior]
  );

  return (
    <div {...lkRowAttrs} {...restProps} data-lk-component="row">
      {children}
    </div>
  );
}

[data-lk-component="row"] {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  gap: 0;
}

/* Align Items */
[data-lk-row-align-items="start"] {
  align-items: flex-start;
}

[data-lk-row-align-items="center"] {
  align-items: center;
}

[data-lk-row-align-items="end"] {
  align-items: flex-end;
}

[data-lk-row-align-items="stretch"] {
  align-items: stretch;
}

/* Justify Content */
[data-lk-row-justify-content="start"] {
  justify-content: flex-start;
}

[data-lk-row-justify-content="center"] {
  justify-content: center;
}

[data-lk-row-justify-content="end"] {
  justify-content: flex-end;
}

[data-lk-row-justify-content="space-between"] {
  justify-content: space-between;
}

[data-lk-row-justify-content="space-around"] {
  justify-content: space-around;
}

/* Gap */
[data-lk-row-gap="3xs"] {
  gap: var(--lk-size-3xs);
}

[data-lk-row-gap="2xs"] {
  gap: var(--lk-size-2xs);
}

[data-lk-row-gap="xs"] {
  gap: var(--lk-size-xs);
}

[data-lk-row-gap="sm"] {
  gap: var(--lk-size-sm);
}

[data-lk-row-gap="md"] {
  gap: var(--lk-size-md);
}

[data-lk-row-gap="lg"] {
  gap: var(--lk-size-lg);
}

[data-lk-row-gap="xl"] {
  gap: var(--lk-size-xl);
}

[data-lk-row-gap="2xl"] {
  gap: var(--lk-size-2xl);
}

[data-lk-row-gap="3xl"] {
  gap: var(--lk-size-3xl);
}

[data-lk-row-gap="4xl"] {
  gap: var(--lk-size-4xl);
}

/* Wrap */
[data-lk-row-wrap-children="true"] {
  flex-wrap: wrap;
}

[data-lk-row-wrap-children="false"] {
  flex-wrap: nowrap;
}

/* Default Child Behavior */
[data-lk-row-default-child-behavior="auto-grow"]>* {
  flex-grow: 1;
  flex-shrink: 0;
  flex-basis: auto;
}

[data-lk-row-default-child-behavior="auto-shrink"]>* {
  flex-grow: 0;
  flex-shrink: 1;
  flex-basis: auto;
}

[data-lk-row-default-child-behavior="ignoreFlexRules"]>* {
  flex-grow: 0;
  flex-shrink: 0;
  flex-basis: auto;
}

[data-lk-row-default-child-behavior="ignoreIntrinsicSize"]>* {
  flex-basis: 0;
}
